<template>
<view class="application" :class="{'wide-root':store.user?.role==='root'&&['overview','admin'].includes(active)}"><a class="skip-link" href="#main-content">跳到内容</a>
  <header class="app-header"><button class="wordmark" aria-label="NJFU-AUTO-LIB 首页" @click="navigate(store.user?.role==='root'?'dashboard':'overview')">NJFU-AUTO-LIB</button>
    <nav class="top-nav" aria-label="主导航"><button v-for="item in items" :key="item.id" :class="{active:selected===item.id}" :aria-current="selected===item.id?'page':undefined" @click="navigate(item.id)">{{item.label}}</button></nav>
    <view class="header-actions"><button class="service-button" :class="{warning:notice.blocked||store.status.scheduler_warning}" :aria-label="notice.title" @click="serviceOpen=true"><AppIcon :name="notice.blocked?'wifi-off':'wifi'"/><text>{{notice.blocked?'服务需检查':store.status.allow_live?'服务正常':'仅查询'}}</text></button><SessionBar :before-leave="beforeLeave"/></view>
  </header>
  <main id="main-content" class="shell" tabindex="-1"><InboxNotice :user="store.user" :status="store.status" @relogin="relogin"/><slot/></main>
  <nav class="bottom-nav" aria-label="主导航"><button v-for="item in items" :key="item.id" :class="{active:selected===item.id}" :aria-current="selected===item.id?'page':undefined" @click="navigate(item.id)"><AppIcon :name="item.icon"/><text>{{item.label}}</text></button></nav>
  <AppDialog :open="serviceOpen" title="服务状态" @close="serviceOpen=false"><SchedulerStatus :status="store.status"/><view v-if="statusError" class="notice error">{{statusError}}</view><view class="status-grid"><text>后台调度</text><strong>{{store.status.scheduler_running?'运行中':'未运行'}}</strong><text>时钟校验</text><strong>{{store.status.clock_ok?'正常':'待检查'}}</strong><text>提交并发上限</text><strong>{{store.status.capacity||'—'}}</strong></view><p class="hint">关闭网页不会关闭已开启计划。放号时需保持执行电脑唤醒，并连通校园网。</p><template #footer><button class="button secondary" :disabled="checking" @click="checkStatus">{{checking?'检查中…':'重新检查'}}</button></template></AppDialog>
</view>
</template>
<script setup>
import {computed,ref} from 'vue';import {useWorkspace} from '@/stores/workspace.js';
import {navigationItems,navigationRoute,activeNavigation} from '@/services/navigation.mjs';import {schedulerNotice} from '@/services/scheduler_status.mjs';
import AppIcon from '@/components/AppIcon.vue';import AppDialog from '@/components/AppDialog.vue';import SessionBar from '@/components/SessionBar.vue';import SchedulerStatus from '@/components/SchedulerStatus.vue';
import InboxNotice from '@/components/InboxNotice.vue';
const props=defineProps({active:{type:String,default:'overview'},beforeLeave:Function});const store=useWorkspace(),serviceOpen=ref(false),checking=ref(false),statusError=ref('');
const items=computed(()=>navigationItems(store.user?.role)),selected=computed(()=>activeNavigation(store.user?.role,props.active)),notice=computed(()=>schedulerNotice(store.status));
async function relogin(){if(props.beforeLeave&&!await props.beforeLeave())return;try{await store.logout();uni.reLaunch({url:'/pages/login/login'});}catch(e){statusError.value=e.message;}}
async function navigate(id){const route=navigationRoute(store.user?.role,id);if(!route||props.beforeLeave&&!await props.beforeLeave())return;uni.reLaunch({url:route});}
async function checkStatus(){checking.value=true;statusError.value='';try{await store.refresh();}catch(e){statusError.value=e.message;}finally{checking.value=false;}}
</script>
<style scoped>
.wide-root .shell{max-width:1344px}.app-header{min-height:88px;padding:17px max(32px,calc((100vw - 1120px)/2));display:flex;align-items:center;gap:28px;border-bottom:1px solid var(--line);background:var(--wash)}.wordmark{font-size:23px;font-weight:760;letter-spacing:-.6px;white-space:nowrap;padding:0;min-height:44px;line-height:1;background:none;margin:0}.top-nav{display:flex;align-items:center;gap:24px;margin:0 auto;align-self:stretch}.top-nav>button{min-width:44px;position:relative;font-size:15px;font-weight:550;padding:8px 0;white-space:nowrap;color:var(--muted);min-height:44px;margin:0;background:none;border-radius:0}.top-nav>button.active{color:var(--green);border-bottom:3px solid var(--green)}.header-actions{display:flex;align-items:center;gap:12px;margin-left:auto}.service-button{min-width:44px;justify-content:center;display:flex;align-items:center;gap:6px;min-height:44px;color:var(--muted);font-size:12px;white-space:nowrap;margin:0;padding:0;background:none}.service-button :deep(.app-icon){width:16px;height:16px}.warning{color:var(--amber)}.bottom-nav{display:none}.status-grid{display:grid;grid-template-columns:1fr auto;gap:20px;font-size:15px}.skip-link{position:fixed;top:-100px;left:16px;z-index:900;padding:12px;background:white;color:var(--green)}.skip-link:focus{top:10px}@media(max-width:1050px){.app-header{padding:16px 24px;gap:18px}.wordmark{font-size:20px}.top-nav{gap:18px}}@media(max-width:599px){.app-header{min-height:68px;padding:12px 16px;gap:12px}.wordmark{font-size:18px}.top-nav{display:none}.service-button text{display:none}.header-actions{gap:8px}.bottom-nav{display:flex;position:fixed;z-index:100;bottom:0;left:0;right:0;justify-content:space-around;min-height:68px;padding:6px 12px max(6px,env(safe-area-inset-bottom));border-top:1px solid var(--line);background:var(--wash)}.bottom-nav button{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;font-size:11px;color:var(--muted);margin:0;padding:5px 14px;min-height:52px;min-width:76px;background:none;line-height:1.4}.bottom-nav button.active{color:var(--green);font-weight:650}.bottom-nav :deep(.app-icon){width:23px;height:23px}}
</style>
